export type Groups = ReturnType<typeof createGroups>;

export const errorTags = [
  "CommandNotFoundError",
  "ConflictError",
  "FeatureDisabledError",
  "ForbiddenError",
  "InvalidCursorError",
  "InvalidRequestError",
  "MessageNotFoundError",
  "MemoryNotFoundError",
  "PeerAuthError",
  "PeerNotConfiguredError",
  "PeerScopeError",
  "PeerUnreachableError",
  "PermissionDeniedError",
  "RequestNotFoundError",
  "ReviewTargetError",
  "RewindConflictError",
  "ServiceUnavailableError",
  "BudgetExceededError",
  "SessionBusyError",
  "SessionNotFoundError",
  "TaskClaimedError",
  "TaskDependencyError",
  "TeamLimitError",
  "TeamNotFoundError",
  "UnauthorizedError",
  "UnknownError",
] as const;

export type ErrorTag = (typeof errorTags)[number];

/** An error carrying a server `_tag`, such as `CyberApiError`. */
export interface TaggedError<Tag extends string = string> {
  readonly tag: Tag;
  readonly status: number;
  readonly body: S.ErrorBody;
}

function hasTag(err: unknown, tag: string): boolean {
  return typeof err === "object" && err !== null && (err as { tag?: unknown }).tag === tag;
}

export function isCommandNotFoundError(err: unknown): err is TaggedError<"CommandNotFoundError"> {
  return hasTag(err, "CommandNotFoundError");
}

export function isConflictError(err: unknown): err is TaggedError<"ConflictError"> {
  return hasTag(err, "ConflictError");
}

export function isFeatureDisabledError(err: unknown): err is TaggedError<"FeatureDisabledError"> {
  return hasTag(err, "FeatureDisabledError");
}

export function isForbiddenError(err: unknown): err is TaggedError<"ForbiddenError"> {
  return hasTag(err, "ForbiddenError");
}

export function isInvalidCursorError(err: unknown): err is TaggedError<"InvalidCursorError"> {
  return hasTag(err, "InvalidCursorError");
}

